import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.C9jfXJBR.js";const u=JSON.parse('{"title":"Production Database Migration Runbook","description":"Safely validate and apply committed BlendSDK PostgreSQL migrations in production","frontmatter":{"title":"Production Database Migration Runbook","description":"Safely validate and apply committed BlendSDK PostgreSQL migrations in production"},"headers":[],"relativePath":"guides/database-migrations-production.md","filePath":"guides/database-migrations-production.md","lastUpdated":1787885988000}'),o={name:"guides/database-migrations-production.md"};function s(r,e,d,l,p,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="production-database-migration-runbook" tabindex="-1">Production Database Migration Runbook <a class="header-anchor" href="#production-database-migration-runbook" aria-label="Permalink to &quot;Production Database Migration Runbook&quot;">​</a></h1><p>Production runs only committed, reviewed migration files. It never generates a schema diff from a live database. Use one dedicated migration job, separate it from application replicas, and keep the ordinary application role unable to change schema where deployment policy permits.</p><p>Zero downtime is not guaranteed for every PostgreSQL change. Use expand–migrate–contract when it fits; schedule a maintenance window when lock duration, table rewrite, backfill, or incompatible application behavior cannot be made safe online.</p><h2 id="before-the-deployment" tabindex="-1">Before the deployment <a class="header-anchor" href="#before-the-deployment" aria-label="Permalink to &quot;Before the deployment&quot;">​</a></h2><ul><li>Provide <code>DATABASE_URL</code> (or the configured variable) from the deployment secret store. Require PostgreSQL TLS according to your environment; do not put credentials in arguments or logs.</li><li>Use a migration role with only the DDL/data privileges required by the reviewed release.</li><li>Confirm infrastructure backups, point-in-time recovery, capacity, and restore testing. BlendSDK migration history is an audit trail, not a backup system.</li><li>Ensure only one job can advance this database. BlendSDK&#39;s advisory lock is the final database guard, not a replacement for deployment orchestration.</li><li>Set lock and statement timeouts deliberately. A timeout is a failure, never a reason to mark a migration applied manually.</li></ul><h2 id="stage-1-build-and-review" tabindex="-1">Stage 1: Build and review <a class="header-anchor" href="#stage-1-build-and-review" aria-label="Permalink to &quot;Stage 1: Build and review&quot;">​</a></h2><p>Generate locally, review exact SQL and safety classification, test on representative disposable PostgreSQL, and commit the <code>.up.sql</code> file with <code>schema.snapshot.json</code>. For expand–migrate–contract, the first release adds compatible nullable structures; later releases backfill and switch reads; only the final release removes the old structure.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --offline</span></span></code></pre></div><p>The release artifact must contain exactly the reviewed immutable migration prefix.</p><h2 id="stage-2-preflight-the-target" tabindex="-1">Stage 2: Preflight the target <a class="header-anchor" href="#stage-2-preflight-the-target" aria-label="Permalink to &quot;Stage 2: Preflight the target&quot;">​</a></h2><p>Run from the same network and role as the migration job. Check current state and prove lock availability without mutation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>Stop if history is invalid, a dirty row exists, the target is locked, backups are unhealthy, or the pending list differs from the reviewed release.</p><h2 id="stage-3-apply-once" tabindex="-1">Stage 3: Apply once <a class="header-anchor" href="#stage-3-apply-once" aria-label="Permalink to &quot;Stage 3: Apply once&quot;">​</a></h2><p>Pause conflicting administrative DDL and start exactly one short-lived migration job:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><p>Do not run <code>up</code> independently in every application replica. Transactional migrations commit SQL and ledger state together. Explicit nontransactional migrations run alone and retain a blocking dirty state whenever success cannot be proved.</p><h2 id="stage-4-verify-database-state" tabindex="-1">Stage 4: Verify database state <a class="header-anchor" href="#stage-4-verify-database-state" aria-label="Permalink to &quot;Stage 4: Verify database state&quot;">​</a></h2><p>Require a successful exit and then verify again:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blendsdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span></code></pre></div><p>Expected state is <code>UP_TO_DATE</code>. Capture the sanitized state and migration IDs in deployment logs; never enable routine SQL, data, connection URL, or credential logging.</p><h2 id="stage-5-roll-the-application-and-observe" tabindex="-1">Stage 5: Roll the application and observe <a class="header-anchor" href="#stage-5-roll-the-application-and-observe" aria-label="Permalink to &quot;Stage 5: Roll the application and observe&quot;">​</a></h2><p>Deploy the application version compatible with the expanded schema, run health checks, and watch database locks, statement latency, error rate, and application compatibility. Complete backfills with separately reviewed application/data tooling. Contract old columns or tables only in a later release after no deployed code depends on them.</p><p>If verification or application rollout fails, stop and use forward recovery. Ship a new reviewed migration or an application compatibility fix; do not edit applied files, fake ledger rows, or use an unreviewed production <code>down</code>.</p><h2 id="failure-and-recovery-matrix" tabindex="-1">Failure and recovery matrix <a class="header-anchor" href="#failure-and-recovery-matrix" aria-label="Permalink to &quot;Failure and recovery matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Proven state</th><th>Required response</th></tr></thead><tbody><tr><td>Advisory lock unavailable</td><td>No migration SQL executed</td><td>Confirm the other job, then retry only after it exits</td></tr><tr><td>Validation/history mismatch</td><td>No migration SQL executed</td><td>Restore the reviewed committed files or investigate the target database; never force the ledger</td></tr><tr><td>Transactional SQL failure</td><td>The failed SQL and ledger insert rolled back</td><td>Diagnose the failure, correct only a not-yet-applied file according to repository policy, and rerun</td></tr><tr><td>Connection loss during transaction</td><td>PostgreSQL determines rollback or commit; BlendSDK does not claim success</td><td>Run <code>validate</code> and <code>status</code>; investigate the database when the ledger cannot prove the outcome</td></tr><tr><td>Nontransactional interruption</td><td>Outcome unknown; a durable dirty row blocks mutation</td><td>Stop, have a DBA inspect the exact database effect, reconcile manually, then ship reviewed forward recovery</td></tr><tr><td>Application incompatible after successful migration</td><td>The database migration remains applied</td><td>Roll application code forward or back only while schema compatibility permits; otherwise deploy a reviewed forward database fix</td></tr></tbody></table><p>Automatic retries are safe only before SQL dispatch and are not provided as a repair mechanism. Never retry unknown nontransactional work blindly.</p><h2 id="existing-production-database-adoption" tabindex="-1">Existing production database adoption <a class="header-anchor" href="#existing-production-database-adoption" aria-label="Permalink to &quot;Existing production database adoption&quot;">​</a></h2><p>Adoption is a one-time operation, not a shortcut around history. Generate and review the baseline, quiesce all application and administrative DDL, run the comparison preview, verify the credential-free target, and provide the exact <code>&lt;database&gt;/&lt;baseline-id&gt;</code> confirmation. BlendSDK repeats the comparison under its advisory lock before inserting the first ledger row. Any modeled difference aborts without running baseline SQL.</p><p>After adoption, run <code>status</code> and <code>validate</code>, retain the committed baseline/snapshot, and use the normal five-stage flow for every later change.</p><h2 id="planned-disruption" tabindex="-1">Planned disruption <a class="header-anchor" href="#planned-disruption" aria-label="Permalink to &quot;Planned disruption&quot;">​</a></h2><p>Choose a maintenance window when the safe lock/rewrite duration is unknown, a required column cannot be expanded compatibly, or a backfill and constraint validation cannot be separated. Drain or pause incompatible traffic, communicate the window, apply once, verify, and restore traffic. The goal is controlled disruption with a tested recovery path—not a claim that disruption is always avoidable.</p><p>Return to the <a href="./database-migrations.html">developer migration workflow</a> for configuration, baseline, generation, and command details.</p>`,33)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
